import Config

# Note we also include the path to a cache manifest
# containing the digested version of static files. This
# manifest is generated by the `mix assets.deploy` task,
# which you should run after static files are built and
# before starting your production server.
config :bitblocks, BitblocksWeb.Endpoint,
  cache_static_manifest: "priv/static/cache_manifest.json",
  url: [port: 443, scheme: "https", host: "www.bitblocks.app"],
  force_ssl: [rewrite_on: [:x_forwarded_proto], exclude: [paths: ["/healthz"]]]

# Configures Swoosh API Client
config :swoosh, api_client: Swoosh.ApiClient.Finch, finch_name: Bitblocks.Finch

# Disable Swoosh Local Memory Storage
config :swoosh, local: false

# Do not print debug messages in production
config :logger, level: :info

# The sync loop works two blocks at a time by default. Each instance is a
# t3.medium (2 vCPU), so CPU cores bind first: POOL_SIZE 10 minus a reserve
# of 5 leaves 5, and the node's RPC limit is 4. An admin can lower it on /sync.
config :bitblocks, :sync_workers, 2

# Blocks stop at 400,000 until the storage plan lands (Ryan, 2026-11-13;
# docs/STORAGE_PLAN.md); headers keep syncing to the tip. SYNC_STOP_AT_HEIGHT
# overrides it at runtime, and SYNC_STOP_AT_HEIGHT=none clears it.
config :bitblocks, :sync_stop_at_height, 400_000

config :bitblocks, Oban,
  queues: [
    default: 10,
    sync: 1,
    sync_blocks: 1,
    derived: 1,
    backfills: 1,
    blocks: 1,
    webhooks: 5,
    collections: 1
  ]

# Runtime production configuration, including reading
# of environment variables, is done on config/runtime.exs.
